package gateway

import (
	"encoding/json"
	"net/http"
	"strings"
	"testing"

	"github.com/gentility-ai/gentility/connector/internal/contracttest"
)

// The wire vectors were generated by the server and checked against its
// peer-signature and internal-bearer verifiers. Sign and Bearer below document
// the byte format; these fixed inputs prove the implementations agree.
//
// The fourth row is deliberately awkward: a one-character secret, a timestamp
// of 0 and a fully compressed address. A timestamp is canonical decimal —
// "0", never "+0" or "00" — and the zero case is where a Go implementation
// that reached for padding would show it.
type wireVector struct {
	Name   string `json:"name"`
	Secret string `json:"secret"`
	Peer   string `json:"peer"`
	UnixTs int64  `json:"unix_ts"`
	Sig    string `json:"signature"`
	Bearer string `json:"bearer"`
}

func wireVectors(t *testing.T) []wireVector {
	t.Helper()
	var fixture struct {
		Vectors []wireVector `json:"vectors"`
	}
	if err := json.Unmarshal(contracttest.Read(t, "connector/peer_header_vectors.json"), &fixture); err != nil {
		t.Fatal(err)
	}
	if len(fixture.Vectors) == 0 {
		t.Fatal("server contract has no peer header vectors")
	}
	return fixture.Vectors
}

func TestSignMatchesTheElixirVectors(t *testing.T) {
	for _, vector := range wireVectors(t) {
		t.Run(vector.Name, func(t *testing.T) {
			if got := Sign([]byte(vector.Secret), vector.Peer, vector.UnixTs); got != vector.Sig {
				t.Errorf("Sign = %q, the Elixir side signs %q", got, vector.Sig)
			}
		})
	}
}

func TestBearerMatchesTheElixirVectors(t *testing.T) {
	for _, vector := range wireVectors(t) {
		t.Run(vector.Name, func(t *testing.T) {
			got, err := Bearer([]byte(vector.Secret), vector.UnixTs)
			if err != nil {
				t.Fatalf("Bearer: %v", err)
			}
			if got != vector.Bearer {
				t.Errorf("Bearer = %q, the Elixir side mints %q", got, vector.Bearer)
			}
		})
	}
}

// The encoding is unpadded and url-safe, and the app has no fallback: a `=`,
// a `+` or a `/` in either value is refused as bad_signature. Asserting the
// alphabet as well as the vectors says which property broke when one changes.
func TestSignaturesAreUnpaddedAndURLSafe(t *testing.T) {
	for _, vector := range wireVectors(t) {
		bearer, err := Bearer([]byte(vector.Secret), vector.UnixTs)
		if err != nil {
			t.Fatalf("Bearer: %v", err)
		}

		for _, value := range []string{Sign([]byte(vector.Secret), vector.Peer, vector.UnixTs), bearer} {
			if strings.ContainsAny(value, "=+/") {
				t.Errorf("%q is not raw url-safe base64", value)
			}
		}
	}
}

// The MAC covers both halves. Either alone would be a hole the contract names:
// signing the address alone makes every past header valid forever, and signing
// the time alone lets one captured signature name any address for the window.
func TestSignCoversBothThePeerAndTheTimestamp(t *testing.T) {
	secret := []byte("overlay wire vector secret")
	base := Sign(secret, "fd06:6e7:0:1::2", 1756000000)

	if other := Sign(secret, "fd06:6e7:0:1::9", 1756000000); other == base {
		t.Error("a different peer produced the same signature")
	}
	if other := Sign(secret, "fd06:6e7:0:1::2", 1756000001); other == base {
		t.Error("a different timestamp produced the same signature")
	}
	if other := Sign([]byte("wrong"), "fd06:6e7:0:1::2", 1756000000); other == base {
		t.Error("a different secret produced the same signature")
	}
}

// The bearer is keyed by a DERIVED key, never by the raw secret. Without that
// separation a captured peer signature and a captured bearer would be the same
// kind of thing, and the app's own test asserts the same property from its
// side.
func TestBearerIsNotKeyedByTheRawSecret(t *testing.T) {
	secret := []byte("overlay wire vector secret")

	bearer, err := Bearer(secret, 1756000000)
	if err != nil {
		t.Fatalf("Bearer: %v", err)
	}

	if strings.Contains(bearer, Sign(secret, "gateway", 1756000000)) {
		t.Error("the bearer's MAC is the raw-secret MAC over the same payload")
	}
}

func TestStripPeerHeadersDeletesEveryCasing(t *testing.T) {
	header := http.Header{}
	header["X-Overlay-Peer"] = []string{"fd06:6e7:0:1::evil"}
	header["x-overlay-peer-ts"] = []string{"1756000000"}
	header["X-OVERLAY-PEER-SIG"] = []string{"forged"}
	header["X-Overlay-Peer-Something-Later"] = []string{"invented in a future capver"}
	header["Authorization"] = []string{"Bearer keep-me"}
	header["X-Node-Capver"] = []string{"1"}

	stripPeerHeaders(header)

	for name := range header {
		if strings.HasPrefix(strings.ToLower(name), "x-overlay-peer") {
			t.Errorf("%s survived the strip", name)
		}
	}
	if header.Get("Authorization") != "Bearer keep-me" {
		t.Error("the strip took a header that was not the client's to lose")
	}
	if header.Get("X-Node-Capver") != "1" {
		t.Error("the strip took the capver header")
	}
}
